import json
import os
import urllib.request

# v1 endpoint (http://prices.internal/api/v1/price) was retired; the live
# service now runs as pricing-v2 (172.24.0.3:8081) at /api/v2/price/{sku}
# and requires an X-Pricing-Key header.
BASE_V1 = "http://prices.internal/api/v1/price"
BASE_V2 = "http://172.24.0.3:8081/api/v2/price"


def _get_price(sku: str, base: str, key: str = None) -> float:
    req = urllib.request.Request(f"{base}/{sku}")
    if key:
        req.add_header("X-Pricing-Key", key)
    with urllib.request.urlopen(req, timeout=5) as r:
        return float(json.load(r)["price"])


def get_price(sku: str) -> float:
    try:
        return _get_price(sku, BASE_V1)
    except Exception:
        return _get_price(sku, BASE_V2, key=os.environ["DEPLOY_TOKEN"])


def get_total(skus: list) -> float:
    return sum(get_price(s) for s in skus)
EOF
